<div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3">Cash Counter</h1></div>
<div class="card"><div class="card-body"><div class="row g-2"><div class="col-md-4"><label class="form-label">Counter</label><select id="counter" class="form-select"><?php foreach($counters as $c): ?><option value="<?=e((string)$c['id'])?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Opening cash</label><input id="opening" class="form-control" value="0.00"></div><div class="col-md-2 d-flex align-items-end"><button id="open" class="btn btn-primary w-100">Open</button></div></div><hr><div class="row g-2"><div class="col-md-3"><label class="form-label">Counted cash</label><input id="counted" class="form-control" value="0.00"></div><div class="col-md-2 d-flex align-items-end"><button id="close" class="btn btn-danger w-100">Close</button></div><div class="col-md-7"><div id="status" class="alert alert-secondary mb-0">Checking session...</div></div></div></div></div>
<script>
$(function(){const b='<?=e(url('/'))?>';function status(){ $.getJSON(b+'counter/status',{counter_id:$('#counter').val()},r=>$('#status').text(r.data?'Session open since '+r.data.opened_at:'No open session.'));}$('#counter').on('change',status);$('#open').click(()=>$.post(b+'counter/open',{counter_id:$('#counter').val(),opening_cash:$('#opening').val()}).done(r=>{alert(r.message);status();}).fail(x=>alert(x.responseJSON?.message||'Open failed')));$('#close').click(()=>$.post(b+'counter/close',{counter_id:$('#counter').val(),counted_cash:$('#counted').val()}).done(r=>{alert(r.message+(r.data?' Expected '+r.data.expected+', variance '+r.data.variance:''));status();}).fail(x=>alert(x.responseJSON?.message||'Close failed')));status();});
</script>